  ('60ea7518-e31d-4abe-9a3e-8b73e8f15fa0', '9918228a-ac42-4a4f-9e9e-17091ce069f9', null, 'topic'::public.curated_course_node_type, 'Engineering Data, Uncertainty, and Statistical Thinking', 'Introduce variation, uncertainty, data quality, and the role of probability/statistics in engineering decisions.', 0),
